const readCTFRevision = `-- name: ReadCTFRevision :one
SELECT payload,published FROM ctf_revision WHERE workspace_id=$1 AND strategy_id=$2 AND revision=$3 AND (user_id=$4 OR published)
`

type ReadCTFRevisionParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	StrategyID  pgtype.UUID `json:"strategy_id"`
	Revision    int32       `json:"revision"`
	UserID      pgtype.UUID `json:"user_id"`
}

type ReadCTFRevisionRow struct {
	Payload   []byte `json:"payload"`
	Published bool   `json:"published"`
}

func (q *Queries) ReadCTFRevision(ctx context.Context, arg ReadCTFRevisionParams) (ReadCTFRevisionRow, error) {
	row := q.db.QueryRow(ctx, readCTFRevision,
		arg.WorkspaceID,
		arg.StrategyID,
		arg.Revision,
		arg.UserID,
	)
	var i ReadCTFRevisionRow
	err := row.Scan(&i.Payload, &i.Published)
	return i, err
}

